          <span className="font-bold tracking-tighter text-2xl text-charcoal">UMKM STORE</span>
        </div>
        <nav className="hidden md:flex items-center gap-8">
          <button onClick={() => scrollToSection('features')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">Fitur</button>
          <button onClick={() => scrollToSection('testimonials')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">Testimoni</button>
          <button onClick={() => scrollToSection('pricing')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">Harga</button>
