    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80;
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      window.scrollTo({
        top: elementPosition - offset,
        behavior: 'smooth'
      });
    }
  };

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'glass-effect py-4 shadow-sm' : 'bg-transparent py-6'}`}>
      <div className="max-w-[1400px] mx-auto px-8 flex items-center justify-between">
        <div className="flex items-center gap-2 cursor-pointer" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>
          <img src="https://ik.imagekit.io/hijar/favicon_orange_nZdGmQxhG.png?updatedAt=null&ik-s=685129b0471afd2427ce908f768034ce5563ba3b" className="h-8 w-auto" />
          <span className="font-bold tracking-tighter text-2xl text-charcoal hidden md:inline-block">First Page Template</span>
        </div>
        <nav className="hidden md:flex items-center gap-8">
          <button onClick={() => scrollToSection('features')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">Fitur</button>
          <button onClick={() => scrollToSection('how-it-works')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">Cara Kerja</button>
          <button onClick={() => scrollToSection('testimonials')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">Testimoni</button>
          <button onClick={() => scrollToSection('pricing')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">Harga</button>
          <button onClick={() => scrollToSection('faq')} className="text-sm font-medium text-charcoal/60 hover:text-primary transition-colors">FAQ</button>
        </nav>
        <div className="flex items-center gap-4">
          <button onClick={onOpenDemo} className="px-6 h-10 border border-charcoal/10 rounded-btn text-sm font-medium hover:bg-soft-peach transition-all">
            Demo
          </button>
          <button onClick={() => scrollToSection('pricing')} className="px-6 h-10 bg-primary text-white rounded-btn text-sm font-medium hover:bg-burnt-orange transition-all">
